export function requireNonEmptyString(
  value: unknown,
  field: string,
): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new ValidationError(`Field ${field} must be a non-empty string`, {
      field,
      reason: "required",
    });
  }

  return value.trim();
}
